=== PROGRAM ===
method addArrays(a : array<int>, b : array<int>) returns (c : array<int>) 
requires a.Length == b.Length
ensures b.Length == c.Length
ensures forall i:int :: 0 <= i <c.Length ==> c[i] == a[i] + b[i] && i != 0

{
     c := new int[a.Length];
     var j := 0;
     while (j < a.Length) 
       invariant 0 <= j <= c.Length
       invariant forall i :: (0 <= i < j) ==> c[i] == a[i] + b[i];
     {    
          c[j] := a[j] + b[j];
          j := j + 1;      
    }
}

=== DAFNY ERROR ===
program.dfy(6,0): Error: a postcondition could not be proved on this return path

program.dfy(4,8): Related location: this is the postcondition that could not be proved
